CREATE OR REPLACE FUNCTION public.link_individual_employee(_user_id uuid, _employee_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT app_private.has_role(auth.uid(), 'root'::public.app_role) THEN RAISE EXCEPTION 'Only root can link accounts'; END IF; IF NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = 'user2') OR EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role <> 'user2') THEN RAISE EXCEPTION 'Account must have only the User2 role'; END IF; PERFORM 1 FROM public.employees WHERE id = _employee_id AND (user_id IS NULL OR user_id = _user_id) FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Employee unavailable or already linked'; END IF; UPDATE public.employees SET user_id = NULL WHERE user_id = _user_id AND id <> _employee_id; UPDATE public.employees SET user_id = _user_id WHERE id = _employee_id; UPDATE public.profiles SET company_id = (SELECT company_id FROM public.employees WHERE id = _employee_id) WHERE id = _user_id; END; $$; REVOKE ALL ON FUNCTION public.link_individual_employee(uuid,uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.link_individual_employee(uuid,uuid) TO authenticated, service_role;